var a={key:"cardano",nombre:"F\xF3rmula de Cardano",familia:"polinomios",resumen:"Resuelve la c\xFAbica a\xB7x\xB3 + b\xB7x\xB2 + c\xB7x + d = 0 en forma cerrada: la reduce a su forma deprimida con el cambio x = t \u2212 b/(3a) y aplica la f\xF3rmula de radicales \u2014 o la trigonom\xE9trica de Vi\xE8te cuando el discriminante es negativo. Cero iteraciones: la respuesta sale de una sola cuenta.",color:"#ec4899"},e=[{key:"paso",label:"Paso",align:"left"},{key:"etapa",label:"Etapa",align:"left"},{key:"detalle",label:"Detalle",align:"left"},{key:"valor",label:"Valor",align:"right"}],o=[{key:"funcion",etiqueta:"Funci\xF3n f(x)",ayuda:"La c\xFAbica igualada a cero, con x como variable. Se admiten ^ para potencias. Tiene que ser de grado 3: si es de grado menor, de grado mayor o no es polinomio (e\u02E3, sen(x)), el m\xE9todo lo detecta y avisa.",requisito:"Grado 3: a\xB7x\xB3 + b\xB7x\xB2 + c\xB7x + d = 0",valorInicial:"x^3 - x - 2",tipo:"text",placeholder:"x^3 - x - 2"}],l={funcion:"x^3 - x - 2"},r={min:-1,max:4};export{a,e as b,o as c,l as d,r as e};
